import { useEffect, useState } from "react";
import axios from "axios";
import { QRCodeCanvas } from "qrcode.react";

function Dashboard() {
  const [name, setName] = useState("");
  const [queues, setQueues] = useState([]);
  const [notification, setNotification] = useState("");

  // Fetch Queue List
  const fetchQueues = async () => {
    const res = await axios.get(
      "http://localhost:5000/api/queue/all"
    );

    setQueues(res.data);
  };

  useEffect(() => {
    fetchQueues();
  }, []);

  // Add Queue
  const addQueue = async () => {
    if (!name) {
      alert("Enter Customer Name");
      return;
    }

    const res = await axios.post(
      "http://localhost:5000/api/queue/add",
      {
        customerName: name
      }
    );

    setNotification(
      `Token ${res.data.tokenNumber} Generated Successfully`
    );

    setName("");
    fetchQueues();
  };

  // Complete Queue
  const updateStatus = async (id, status) => {
    await axios.put(
      `http://localhost:5000/api/queue/update/${id}`,
      {
        status
      }
    );

    setNotification("Queue Completed");

    fetchQueues();
  };

  return (
    <div style={{ padding: "50px" }}>
      <h1>Smart Queue Dashboard</h1>

      {/* Notification */}
      {notification && (
        <div
          style={{
            backgroundColor: "lightgreen",
            padding: "10px",
            marginBottom: "20px"
          }}
        >
          {notification}
        </div>
      )}

      {/* Input */}
      <input
        type="text"
        placeholder="Customer Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />

      <button onClick={addQueue}>
        Generate Token
      </button>

      <hr />

      {/* Queue List */}
      {queues.map((q) => (
        <div
          key={q._id}
          style={{
            border: "1px solid black",
            padding: "15px",
            marginBottom: "20px"
          }}
        >
          <h3>Token: {q.tokenNumber}</h3>

          <p>Name: {q.customerName}</p>

          <p>Status: {q.status}</p>

          {/* QR CODE */}
          <QRCodeCanvas
            value={`Token:${q.tokenNumber} Name:${q.customerName}`}
            size={120}
          />

          <br />
          <br />

          <button
            onClick={() =>
              updateStatus(q._id, "Completed")
            }
          >
            Complete
          </button>
        </div>
      ))}
    </div>
  );
}

export default Dashboard;
